"""MinHash / LSH machinery used by dedup.py and split_overlap.py.

Pure numpy + stdlib. 128 hash signatures with b bands of r rows; a pair is a
candidate if it matches in all r rows of any band. With b=24, r=8 the
candidate step starts catching pairs at Jaccard ~ 0.6; the dedup threshold is
enforced afterwards by exact Jaccard verification.
"""
import numpy as np

B, R = 24, 8
NUM_PERM = B * R  # 192


def shingles(text, n=3):
    ws = text.split()
    if len(ws) < n:
        return {" ".join(ws)} if ws else set()
    return {" ".join(ws[i:i + n]) for i in range(len(ws) - n + 1)}


def _vectors(text):
    hs = [stable_hash64(s) for s in shingles(text)]
    if not hs:
        return None, np.zeros(NUM_PERM, dtype=np.uint64)
    arr = np.array(hs, dtype=np.uint64)
    # universal hashing: (a*x + b) mod p, over a 64-bit prime
    a = (PRIME_A * arr) & MASK64
    sig = (a + PRIME_B) & MASK64
    sig = sig.reshape(NUM_PERM, 1)  # placeholder shape guard, see permutation below
    return None, sig


# --- simplest correct implementation: loop-free vectorized permutation ---
# For each of the NUM_PERM permutations i, hash(x, i) = (ai*x + bi) mod 2^64
# computed with numpy uint64 arithmetic (wraps mod 2^64 naturally).

import hashlib

MASK64 = (1 << 64) - 1


def stable_hash64(s: str) -> int:
    return int.from_bytes(hashlib.blake2b(s.encode("utf-8"), digest_size=8).digest(), "big")


AI = np.array([(stable_hash64(f"perm-a-{i}") | 1) for i in range(NUM_PERM)], dtype=np.uint64)
BI = np.array([stable_hash64(f"perm-b-{i}") for i in range(NUM_PERM)], dtype=np.uint64)


def signature(text) -> np.ndarray:
    """192-dim minhash signature of the 3-shingle set of `text` (uint64)."""
    hs = [stable_hash64(s) for s in shingles(text)]
    if not hs:
        return BI.copy()  # degenerate: all-max signature
    arr = np.array(hs, dtype=np.uint64)  # (k,)
    h = (AI[:, None] * arr[None, :] + BI[:, None]) & MASK64  # (NUM_PERM, k)
    return h.min(axis=1)


def band_keys(sig: np.ndarray):
    """Yield bucket keys (one band-grouped tuple of hex blocks, per band)."""
    for b in range(B):
        yield b, tuple(int(v) for v in sig[b * R:(b + 1) * R])


def jaccard(sig1, sig2):
    return float(np.mean(sig1 == sig2))


def exact_jaccard(s1: set, s2: set) -> float:
    if not s1 or not s2:
        return 0.0
    return len(s1 & s2) / len(s1 | s2)
