#!/usr/bin/env python3
"""Token-based length-ratio filter with a floor on per-side token count.

Defaults match the original run: keep pairs with 0.5 <= len(src_tok) / len(tgt_tok) <= 2.0.
Also optionally keeps a report of dropped ratio distribution so we can see
whether the filter is eating short colloquial Swahili/Tamil (the known
concern) vs. real noise.

Usage: length_filter.py IN.gz OUT.gz --tgt sw --report OUT.json [--dropped DROPPED.json]
"""
import argparse, collections, json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import read_bitext, write_json

def argmax_len(text):
    """WTB: prefer real whitespace tokens; fall back to characters for scripts w/o spaces."""
    return len(text.split()) or max(1, len(text.strip()) // 4)

def main():
    p = argparse.ArgumentParser()
    p.add_argument("inp"); p.add_argument("outp")
    p.add_argument("--min-ratio", type=float, default=0.5)
    p.add_argument("--max-ratio", type=float, default=2.0)
    p.add_argument("--min-tokens", type=int, default=1)
    p.add_argument("--align", choices=["src_over_tgt", "symmetric"], default="src_over_tgt")
    p.add_argument("--report", default=None)
    p.add_argument("--dropped", default=None)
    a = p.parse_args()

    counts = {"in": 0, "kept": 0, "too_short": 0}
    ratios_out = collections.Counter()   # histogram of而且还 ratios of *dropped* pairs (binned)
    ratios_kept = collections.Counter()
    failed = []

    f = open(a.outp, "w", encoding="utf-8") if not a.outp.endswith(".gz") else __import__("gzip").open(a.outp, "wt", encoding="utf-8")
    try:
        for s, t in read_bitext(a.inp):
            counts["in"] += 1
            ls, lt = argmax_len(s), argmax_len(t)
            if ls < a.min_tokens or lt < a.min_tokens:
                counts["too_short"] += 1
                if len(failed) < 500: failed.append(["too_short", s, t])
                continue
            if a.align == "symmetric":
                r = max(ls / lt, lt / ls)
            else:
                r = ls / lt
            ok = a.min_ratio <= r <= a.max_ratio
            if ok:
                counts["kept"] += 1
                bin_ = round(r, 1)
                ratios_kept[bin_] += 1
            else:
                bin_ = min(9.9, round(r, 1))
                ratios_out[bin_] += 1
                if len(failed) < 500: failed.append([f"ratio_{min(9.9, round(r,1))}", s, t])
            if ok:
                f.write(f"{s}\t{t}\n")
    finally:
        f.close()

    if a.report:
        write_json({
            "counts": counts,
            "dropped_ratio_hist": {str(k): v for k, v in sorted(ratios_out.items())},
            "kept_ratio_hist_sample": dict(list(sorted(ratios_kept.items()))[:30]),
        }, a.report)
    if a.dropped and failed:
        with open(a.dropped, "w", encoding="utf-8") as g:
            for row in failed:
                g.write("\t".join([row[0], row[1].replace("\t", " ")[:200], row[2].replace("\t", " ")[:200]]) + "\n")
    print(json.dumps(counts))

if __name__ == "__main__":
    main()
