#!/usr/bin/env python3
"""Exact + near (MinHash LSH) dedup over a tab-separated bitext file.

Design (matches the 2026-10-10 run's numbers):
  * Stage A: exact dupes on the key side (src by default -> as in the notes
    minhash/near-dedup stage). Survivors of A go to stage B.
  * Stage B: k-shingle MinHash with num_perm permutations, banded LSH
    (bands x rows <= num_perm), candidate pairs verified with exact Jaccard
    (character-normalised token shingles) >= thr.
  * Within a verified group the canonical row is kept: longest other-side text,
    tie broken by earlier position. Group is written out once.
Shingle k=5 tokens, thr=0.85 -> matches the ~0.85 Jaccard in the notes.

RAM: tgt/src strings are held in memory as python str; 1.5M pairs * ~150B
each on one side is roughly 450 MB plus overhead, fine on this node (62 GB).

Usage: dedup.py IN.gz OUT.gz --thr 0.85 --report OUT.json
"""
import argparse, collections, hashlib, json, os, random, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import read_bitext, write_json

MERSENNE = (1 << 61) - 1
CAND_CAP = 3_000_000

def shingles(text, k=5):
    toks = [t.strip(".,!?;:\"'()[]-–—«»") for t in text.lower().split()]
    toks = [t for t in toks if t]
    if not toks:
        return frozenset()
    if len(toks) < k:
        return frozenset([" ".join(toks)])
    return frozenset(" ".join(toks[i:i + k]) for i in range(len(toks) - k + 1))

def minhash_sig(sh, params):
    if not sh:
        # empty keys hash to a fixed signature so all empties collide (and get
        # verified/f caught in the exact pass anyway)
        return tuple(0 for _ in params)
    blob = "\x1e".join(sorted(sh)).encode("utf-8")
    base = int.from_bytes(hashlib.blake2b(blob, digest_size=16).digest(), "big") % MERSENNE
    return tuple((a * base + b) % MERSENNE for a, b in params)

def jaccard(a, b):
    if not a and not b:
        return 1.0
    inter = len(a & b)
    return inter / (len(a) + len(b) - inter) if inter else 0.0

class UnionFind:
    def __init__(self):
        self.parent = {}
    def find(self, x):
        p = self.parent.setdefault(x, x)
        if p != x:
            self.parent[x] = p = self.find(p)
        return p
    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx != ry:
            # deterministic winner: lexicographically smallest key as representative
            lo, hi = (rx, ry) if rx < ry else (ry, rx)
            self.parent[hi] = lo

def main():
    p = argparse.ArgumentParser()
    p.add_argument("inp"); p.add_argument("outp")
    p.add_argument("--key", choices=["src", "tgt"], default="src",
                   help="which side is used for grouping (default: src, per original run)")
    p.add_argument("--k", type=int, default=5)
    p.add_argument("--num-perm", type=int, default=128)
    p.add_argument("--bands", type=int, default=16)
    p.add_argument("--rows", type=int, default=8)
    p.add_argument("--thr", type=float, default=0.85)
    p.add_argument("--seed", type=int, default=7)
    p.add_argument("--report", default=None)
    p.add_argument("--examples", default=None,
                   help="write up to 200 example dup groups per stage as TSV")
    a = p.parse_args()
    assert a.bands * a.rows <= a.num_perm

    rng = random.Random(a.seed)
    params = [(rng.randrange(1, MERSENNE), rng.randrange(0, MERSENNE)) for _ in range(a.num_perm)]

    counts = {"in": 0, "exact_dupes": 0, "near_candidates": 0, "near_dupes": 0, "kept": 0}
    examples = {"exact": [], "near": []}

    # ---------- stage A: exact dupes, keep canonical row per key
    # key -> (position of representative row, its other-side length)
    canon = {}
    uf_exact_parent = {}
    rows_key = []   # for each input row, its key (cheap; needed for stage B input)
    idx_k_src = []  # parallel src texts (all rows). Memory: acceptable, see header.
    idx_k_tgt = []
    for s, t in read_bitext(a.inp):
        i = counts["in"]
        counts["in"] += 1
        key, other, olen = (s, t, len(t)) if a.key == "src" else (t, s, len(s))
        rows_key.append(key)
        idx_k_src.append(s); idx_k_tgt.append(t)
        if key in canon:
            pos, best_len = canon[key]
            uf_exact_parent[i] = pos   # this input row is an exact dupe of pos
            counts["exact_dupes"] += 1
            if a.keep_longest if False else best_len is None or olen > best_len:
                canon[key] = (i, olen)
                uf_exact_parent[pos] = i  # canonical moves to the longer row
        else:
            canon[key] = (i, None)  # best_len set on first update below
            uf_exact_parent.setdefault(i, i)
            canon[key] = (i, olen)
        pass  # (dupe bookkeeping continues: any later row maps to its group)

    print(f"stage A: {counts['in']} rows, {len(canon)} unique keys, {counts['exact_dupes']} exact dupes",
          file=sys.stderr)

    # ---------- stage B: minhash LSH on unique keys
    keys = list(canon.keys())
    sigs = {}
    for key in keys:
        sigs[key] = minhash_sig(shingles(key, a.k), params)
    band_index = collections.defaultdict(list)
    for key, sig in sigs.items():
        for b in range(a.bands):
            sl = sig[b * a.rows:(b + 1) * a.rows]
            h = hashlib.blake2b("".join(f"{v:016x}" for v in sl).encode(), digest_size=8).digest()
            band_index[h].append(key)

    cand = set()
    contented = 0
    for h, ks in band_index.items():
        if len(ks) < 2:
            continue
        contented += 1
        for i in range(len(ks) - 1):
            ki = ks[i]
            si = shingles(ki, a.k)
            for j in range(i + 1, len(ks)):
                if len(cand) >= CAND_CAP:
                    break
                kj = ks[j]
                if jaccard(si, shingles(kj, a.k)) >= a.thr:
                    cand.add((min(ki, kj), max(ki, kj)))
    counts["near_candidates"] = len(cand)

    uf = UnionFind()
    for k1, k2 in cand:
        uf.union(k1, k2)

    # pick representative key per component: the one whose canonical row has
    # the longest other side, ties by earliest position
    best = {}
    for key in keys:
        root = uf.find(key) if key in uf.parent else key
    # note: roots determined after first find pass
    comps = collections.defaultdict(list)
    for key in keys:
        comps[uf.find(key) if key in uf.parent else key].append(key)

    dropped_keys = set()
    keep_row = {}
    for root, members in comps.items():
        if len(members) > 1:
            counts["near_dupes"] += len(members) - 1
            members = sorted(members)
            if len(examples["near"]) < 200:
                examples["near"].append(members[:5])
            dropped_keys.update(members[1:])
        # canonical row of the winner
        w = min(members, key=lambda k: (-canon[k][1], canon[k][0]))
        keep_row[w] = canon[w][0]
    survivors = sorted(keep_row.values())

    opener = __import__("gzip").open if a.outp.endswith(".gz") else open
    with opener(a.outp, "wt", encoding="utf-8") as f:
        for i in survivors:
            f.write(f"{idx_k_src[i]}\t{idx_k_tgt[i]}\n")
            counts["kept"] += 1

    if a.report:
        write_json(counts, a.report)
    if a.examples:
        import gzip as _gz
        op = _gz.open if a.examples.endswith(".gz") else open
        with op(a.examples, "wt", encoding="utf-8") as g:
            for kind, group in examples.items():
                for grp in group:
                    if kind == "exact":
                        g.write(f"exact\t{grp[0]}\t{grp[1]}\n")
                    else:
                        for m in grp:
                            g.write(f"near_grp\t{m[:200]}\n")

    print(json.dumps(counts))

if __name__ == "__main__":
    main()
